{
  "$schema": "https://opencode.ai/config.json",
  "model": "opencode/deepseek-v4-flash-free",
  "default_agent": "jarvis",
  "share": "disabled",
  "instructions": [
    "~/.config/opencode/global-rules.md"
  ],
  "permission": {
    "bash": {
      "*find*": "deny",
      "*grep*": "deny",
      "*npm*": "deny",
      "*sqlite*": "ask",
      "*opencode*": "ask"
    },
    "glob": "deny",
    "grep": "deny",
    "websearch": "deny"
  },
  "mcp": {
    "exa": {
      "type": "remote",
      "url": "http://127.0.0.1:18099",
      "enabled": true,
      "timeout": 120000
    },
    "deepwiki": {
      "type": "remote",
      "url": "https://mcp.deepwiki.com/mcp",
      "enabled": true,
      "timeout": 120000
    },
    "sequential-thinking": {
      "type": "local",
      "command": [
        "/home/kasiro/.bun/bin/mcp-server-sequential-thinking"
      ],
      "timeout": 120000,
      "enabled": true
    },
    "context7": {
      "type": "remote",
      "url": "https://mcp.context7.com/mcp",
      "enabled": true,
      "timeout": 120000,
      "headers": {
        "Authorization": "Bearer ctx7sk-418a5f6a-2b9c-4caa-94e2-573821193500"
      }
    },
    "searxng": {
      "type": "local",
      "command": [
        "mcp-searxng"
      ],
      "enabled": true,
      "timeout": 60000,
      "environment": {
        "SEARXNG_URL": "http://localhost:8099",
        "SEARXNG_MAX_RESULTS": "15"
      },
      "description": "Поиск через свой SearXNG (Docker) + web_url_read"
    },
    "crawl4ai": {
      "type": "local",
      "command": [
        "/home/kasiro/Документы/python_projects/crawl4ai-mcp/.venv/bin/python",
        "-m",
        "crawl4ai_mcp.server"
      ],
      "timeout": 60000,
      "enabled": true,
      "description": "Crawl4AI MCP — краулинг, извлечение данных, sitemap, browser sessions"
    },
    "youtube-transcript": {
      "type": "local",
      "command": [
        "/home/kasiro/Документы/python_projects/yt-transcript-mcp/.venv/bin/yt-transcript-mcp"
      ],
      "environment": {
        "EXA_API_KEY": "57c7932c-0ffa-4f75-8173-da5b8a343752"
      },
      "timeout": 60000,
      "enabled": true
    },
    "chrome-devtools": {
      "type": "local",
      "command": [
        "/home/kasiro/.bun/bin/chrome-devtools-mcp",
        "--executablePath=/opt/brave-bin/brave"
      ],
      "enabled": true,
      "timeout": 60000
    },
    "lightpanda": {
      "type": "local",
      "command": [
        "lightpanda",
        "mcp"
      ],
      "enabled": true,
      "timeout": 60000,
      "description": "Lightpanda headless browser — быстрый MCP скрапинг"
    }
  },
  "agent": {
    "jarvis": {
      "tools": {
        "edit": false,
        "bash": false
      },
      "permission": {
        "edit": {
          "*": "deny"
        },
        "bash": {
          "*": "deny"
        },
        "websearch": "deny",
        "webfetch": "deny",
        "searxng_*": "deny",
        "crawl4ai_*": "deny",
        "deepwiki_*": "deny",
        "context7_*": "deny",
        "exa_*": "deny",
        "youtube-transcript_*": "deny",
        "lightpanda_*": "deny"
      }
    },
    "title": {
      "model": "opencode/big-pickle"
    },
    "general": {
      "permission": {
        "edit": {
          "**/memory/**": "allow",
          "*": "allow"
        },
        "bash": {
          "*grep*": "deny",
          "*find*": "deny",
          "*npx*": "deny",
          "*npm*": "deny",
          "*sqlite*": "ask",
          "*": "allow"
        },
        "websearch": "allow",
        "webfetch": "allow",
        "skill": {
          "agent-delegation": "deny",
          "jarvis-cycles": "deny",
          "context-mgmt": "deny"
        }
      },
      "tools": {
        "glob": false,
        "grep": false,
        "sequential-thinking_*": true,
        "searxng_*": true,
        "deepwiki_*": true,
        "context7_*": true,
        "exa_*": true,
        "crawl4ai_*": true,
        "youtube-transcript_*": true,
        "lightpanda_*": true
      }
    },
    "explore": {
      "disable": true
    }
  },
  "lsp": {},
  "plugin": [
    "opencode-intellisearch",
    "@tarquinen/opencode-dcp@3.1.13",
    "opencode-agent-memory"
  ],
  "compaction": {
    "auto": false,
    "prune": false
  },
  "tool_output": {
    "max_lines": 5000,
    "max_bytes": 204800
  },
  "experimental": {
    "mcp_timeout": 120000
  }
}

{
  "$schema": "https://mimo.xiaomi.com//config.json",
  "plugin": [
    "opencode-intellisearch",
    "@tarquinen/opencode-dcp@latest"
  ],
  "default_agent": "jarvis",
  "provider": {
    "opencode-free": {
      "name": "OpenCode Zen Free",
      "npm": "@ai-sdk/openai-compatible",
      "options": {
        "baseURL": "https://opencode.ai/zen/v1",
        "headers": {
          "Authorization": "Bearer {env:OPENCODE_API_KEY}"
        }
      },
      "models": {
        "deepseek-v4-flash-free": {
          "name": "DeepSeek V4 Flash Free (1M)",
          "limit": {
            "context": 1000000,
            "output": 65536
          },
          "modalities": {
            "input": [
              "text",
              "image"
            ],
            "output": [
              "text"
            ]
          }
        },
        "mimo-v2.5-free": {
          "name": "MiMo V2.5 Free (1M)",
          "limit": {
            "context": 1000000,
            "output": 65536
          }
        },
        "nemotron-3-ultra-free": {
          "name": "Nemotron 3 Ultra Free (1M)",
          "limit": {
            "context": 1000000,
            "output": 65536
          }
        },
        "north-mini-code-free": {
          "name": "North Mini Code Free (1M)",
          "limit": {
            "context": 1000000,
            "output": 65536
          }
        },
        "laguna-s-2.1-free": {
          "name": "Laguna S 2.1 Free (256K)",
          "limit": {
            "context": 256000,
            "output": 65536
          },
          "modalities": {
            "input": ["text"],
            "output": ["text"]
          }
        },
        "big-pickle": {
          "name": "Big Pickle",
          "limit": {
            "context": 1000000,
            "output": 65536
          }
        }
      }
    }
  },
  "mcp": {
    "exa": {
      "type": "remote",
      "url": "http://127.0.0.1:18099",
      "enabled": true,
      "timeout": 30000
    },
    "searxng": {
      "type": "local",
      "command": [
        "mcp-searxng"
      ],
      "environment": {
        "SEARXNG_URL": "http://localhost:8099",
        "SEARXNG_MAX_RESULTS": "15"
      },
      "enabled": true,
      "timeout": 130000
    },
    "deepwiki": {
      "type": "remote",
      "url": "https://mcp.deepwiki.com/mcp",
      "enabled": true
    },
    "sequential-thinking": {
      "type": "local",
      "command": [
        "/home/kasiro/.bun/bin/mcp-server-sequential-thinking"
      ],
      "enabled": true
    },
    "context7": {
      "type": "remote",
      "url": "https://mcp.context7.com/mcp",
      "enabled": true,
      "headers": {
        "Authorization": "Bearer ctx7sk-418a5f6a-2b9c-4caa-94e2-573821193500"
      }
    },
    "youtube-transcript": {
      "type": "local",
      "command": [
        "/home/kasiro/Документы/python_projects/yt-transcript-mcp/.venv/bin/yt-transcript-mcp"
      ],
      "environment": {
        "EXA_API_KEY": "57c7932c-0ffa-4f75-8173-da5b8a343752"
      },
      "enabled": true,
      "timeout": 130000
    },
    "agentmemory": {
      "type": "local",
      "command": [
        "bunx",
        "-y",
        "@agentmemory/mcp"
      ],
      "enabled": false,
      "timeout": 30000
    }
  },
  "instructions": [
    "/home/kasiro/.config/mimocode/instructions.md"
  ],
  "permission": {
    "bash": {
      "rg *": "allow",
      "fd *": "allow",
      "bun *": "allow",
      "bunx *": "allow",
      "find*": "deny",
      "grep*": "deny",
      "npm*": "deny"
    },
    "glob": "deny",
    "grep": "deny",
    "webfetch": "deny",
    "exa_*": "allow",
    "deepwiki_*": "allow",
    "sequential-thinking_*": "allow",
    "context7_*": "allow",
    "youtube-transcript_*": "allow"
  },
  "compaction": {
    "auto": true
  },
  "experimental": {
    "mcp_timeout": 120000
  }
}
